'use client'

import { useCallback, useEffect, useRef, useState } from 'react'
import { findAllByDate } from '../services/visitors'

// Cada cuánto se revisa si llegaron solicitudes nuevas
const POLL_MS = 15000
const SOUND_PREF_KEY = 'femaccess.requestAlerts.sound'

interface LatestRequest {
  id: string
  name: string
  lastnames: string
  date: string
  createdAt: string
}

// ---------------------------------------------------------------------------
// Sonido: un "ding-dong" generado con Web Audio (no necesita archivos de audio).
// Los navegadores solo permiten sonar después de que el usuario interactúa con la
// página, por eso el AudioContext se crea / reanuda en el primer clic o tecla.
// ---------------------------------------------------------------------------
let audioContext: AudioContext | null = null

const getAudioContext = () => {
  if (typeof window === 'undefined') return null
  const Ctx = window.AudioContext || (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext
  if (!Ctx) return null
  if (!audioContext) audioContext = new Ctx()
  return audioContext
}

export const unlockAudio = () => {
  const ctx = getAudioContext()
  if (ctx && ctx.state === 'suspended') ctx.resume().catch(() => undefined)
}

export const playChime = () => {
  const ctx = getAudioContext()
  if (!ctx) return
  if (ctx.state === 'suspended') ctx.resume().catch(() => undefined)
  const now = ctx.currentTime
  // Dos notas: Mi6 → Do6, con caída suave de volumen
  ;[
    { freq: 1318.5, start: 0 },
    { freq: 1046.5, start: 0.18 },
  ].forEach(({ freq, start }) => {
    const osc = ctx.createOscillator()
    const gain = ctx.createGain()
    osc.type = 'sine'
    osc.frequency.value = freq
    gain.gain.setValueAtTime(0.0001, now + start)
    gain.gain.exponentialRampToValueAtTime(0.35, now + start + 0.02)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + start + 0.6)
    osc.connect(gain).connect(ctx.destination)
    osc.start(now + start)
    osc.stop(now + start + 0.65)
  })
}

const readSoundPref = () => {
  try {
    return localStorage.getItem(SOUND_PREF_KEY) !== 'off'
  } catch {
    return true
  }
}

const writeSoundPref = (on: boolean) => {
  try {
    localStorage.setItem(SOUND_PREF_KEY, on ? 'on' : 'off')
  } catch {
    // Sin almacenamiento disponible: la preferencia dura solo esta sesión
  }
}

// ---------------------------------------------------------------------------
// Alertas de solicitudes nuevas para el perfil SEGURIDAD.
// - Revisa cada 15 s las solicitudes PENDIENTES (la más reciente y el total).
// - La primera revisión solo fija la referencia (no suena por las que ya existían).
// - Si aparece una más nueva: sonido + aviso en pantalla + notificación del navegador
//   (esta última solo si la pestaña no está visible y el usuario dio permiso).
// ---------------------------------------------------------------------------
export function useRequestAlerts(enabled: boolean, onNewRequest?: (message: string) => void) {
  const [pendingCount, setPendingCount] = useState(0)
  const [soundOn, setSoundOn] = useState(true)
  const [newRequestsSignal, setNewRequestsSignal] = useState(0)
  const latestSeenRef = useRef<string | null>(null)
  const initializedRef = useRef(false)
  const soundOnRef = useRef(true)
  const onNewRef = useRef(onNewRequest)
  onNewRef.current = onNewRequest

  useEffect(() => {
    const pref = readSoundPref()
    setSoundOn(pref)
    soundOnRef.current = pref
  }, [])

  // Desbloquear el audio con la primera interacción
  useEffect(() => {
    if (!enabled) return
    const unlock = () => unlockAudio()
    window.addEventListener('pointerdown', unlock)
    window.addEventListener('keydown', unlock)
    return () => {
      window.removeEventListener('pointerdown', unlock)
      window.removeEventListener('keydown', unlock)
    }
  }, [enabled])

  const check = useCallback(async () => {
    try {
      // Orden por createdAt desc: data[0] es la solicitud pendiente más reciente
      const response = await findAllByDate(undefined, undefined, 1, 1, undefined, 'PENDIENTE')
      const total: number = response?.meta?.total ?? 0
      const latest: LatestRequest | undefined = response?.data?.[0]
      setPendingCount(total)

      const latestAt = latest?.createdAt ?? null
      if (!initializedRef.current) {
        initializedRef.current = true
        latestSeenRef.current = latestAt
        return
      }
      if (latest && latestAt && (!latestSeenRef.current || latestAt > latestSeenRef.current)) {
        latestSeenRef.current = latestAt
        const message = `Nueva solicitud de visita: ${latest.name} ${latest.lastnames} (${latest.date})`
        if (soundOnRef.current) playChime()
        onNewRef.current?.(message)
        setNewRequestsSignal((n) => n + 1)
        if (
          typeof Notification !== 'undefined' &&
          Notification.permission === 'granted' &&
          document.visibilityState !== 'visible'
        ) {
          try {
            new Notification('FEMAccess · Nueva solicitud', { body: message, tag: 'femaccess-request' })
          } catch {
            // Algunos navegadores no permiten notificaciones fuera de un service worker
          }
        }
      }
    } catch (err) {
      // Si falla una revisión (sin red, etc.) se intenta de nuevo en el siguiente ciclo
      console.error('Error checking new requests:', err)
    }
  }, [])

  useEffect(() => {
    if (!enabled) return
    check()
    const interval = window.setInterval(check, POLL_MS)
    // Al volver a la pestaña se revisa de inmediato
    const onVisible = () => {
      if (document.visibilityState === 'visible') check()
    }
    document.addEventListener('visibilitychange', onVisible)
    return () => {
      window.clearInterval(interval)
      document.removeEventListener('visibilitychange', onVisible)
    }
  }, [enabled, check])

  // Activar / silenciar. Al activar se pide permiso de notificaciones y se prueba el sonido.
  const toggleSound = useCallback(() => {
    const next = !soundOnRef.current
    soundOnRef.current = next
    setSoundOn(next)
    writeSoundPref(next)
    if (next) {
      unlockAudio()
      playChime()
      if (typeof Notification !== 'undefined' && Notification.permission === 'default') {
        Notification.requestPermission().catch(() => undefined)
      }
    }
  }, [])

  return { pendingCount, soundOn, toggleSound, newRequestsSignal, refresh: check }
}
