'use client'

import { useEffect, useRef, useState } from 'react'
import { CalendarDays, Check, RefreshCw, Search, X } from 'lucide-react'
import { approveVisitor, findAllByDate, rejectVisitor } from '../services/visitors'
import { Modal } from './form-modal'
import { stagger } from './motion'
import { VisitStatus, VisitStatusBadge } from './visit-status'
import { isPeriodVisit } from './visit-period'

interface RequestVisitor {
  id: string
  name: string
  lastnames: string
  run: string
  date: string
  endDate?: string | null
  startHour: string
  endHour: string
  createdAt: string
  status: VisitStatus
  reviewedAt?: string | null
  rejectionReason?: string | null
  isArrivalValidated: boolean
  zone?: { id: string; name: string } | null
  contactUser?: { id: string; username: string } | null
  creator?: { id: string; username: string } | null
  reviewer?: { id: string; username: string } | null
}

interface RequestsViewProps {
  // Solo SEGURIDAD aprueba / rechaza. ADMIN y SUPERADMIN ven las solicitudes en modo consulta.
  canReview?: boolean
  onToast?: (message: string) => void
  // Cambia cada vez que llega una solicitud nueva → recarga la lista
  refreshSignal?: number
  // Se llama después de aprobar / rechazar (para actualizar el contador de pendientes)
  onReviewed?: () => void
}

type Tab = VisitStatus | 'TODAS'

const TABS: { id: Tab; label: string }[] = [
  { id: 'PENDIENTE', label: 'Pendientes' },
  { id: 'APROBADA', label: 'Aprobadas' },
  { id: 'RECHAZADA', label: 'Rechazadas' },
  { id: 'CERRADA', label: 'Cerradas' },
  { id: 'TODAS', label: 'Todas' },
]

const getTodayISO = () =>
  new Date().toLocaleDateString('en-CA', { timeZone: 'America/Santiago' })

const getErrorMessage = (err: unknown, fallback: string) => {
  const message = (err as { response?: { data?: { message?: string | string[] } } })
    ?.response?.data?.message
  if (Array.isArray(message)) return message.join(', ')
  return message || fallback
}

const formatDateTime = (value?: string | null) =>
  value
    ? new Date(value).toLocaleString('es-CL', {
        day: '2-digit',
        month: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        timeZone: 'America/Santiago',
      })
    : '—'

// SEGURIDAD solo puede ver, aprobar y rechazar solicitudes (no edita ni elimina)
export default function RequestsView({
  canReview = false,
  onToast,
  refreshSignal = 0,
  onReviewed,
}: RequestsViewProps) {
  const [tab, setTab] = useState<Tab>('PENDIENTE')
  // Por defecto: solicitudes desde hoy en adelante
  const [startDate, setStartDate] = useState(getTodayISO())
  const [endDate, setEndDate] = useState('')
  const [search, setSearch] = useState('')
  const [debouncedSearch, setDebouncedSearch] = useState('')

  const [visits, setVisits] = useState<RequestVisitor[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  const [total, setTotal] = useState(0)
  const pageSize = 10
  const lastRequest = useRef(0)

  const [busyId, setBusyId] = useState<string | null>(null)
  const [toReject, setToReject] = useState<RequestVisitor | null>(null)
  const [rejectReason, setRejectReason] = useState('')
  const [rejectError, setRejectError] = useState('')

  const fetchVisits = async () => {
    const requestId = ++lastRequest.current
    setLoading(true)
    setError('')
    try {
      const response = await findAllByDate(
        startDate || undefined,
        endDate || undefined,
        page,
        pageSize,
        debouncedSearch || undefined,
        tab === 'TODAS' ? undefined : tab
      )
      if (requestId !== lastRequest.current) return
      setVisits(Array.isArray(response?.data) ? response.data : [])
      setTotal(response?.meta?.total ?? 0)
      setTotalPages(Math.max(1, response?.meta?.totalPages ?? 1))
    } catch (err) {
      if (requestId !== lastRequest.current) return
      console.error('Error fetching requests:', err)
      setError(getErrorMessage(err, 'No se pudieron cargar las solicitudes.'))
    } finally {
      if (requestId === lastRequest.current) setLoading(false)
    }
  }

  useEffect(() => {
    const timer = window.setTimeout(() => setDebouncedSearch(search.trim()), 400)
    return () => window.clearTimeout(timer)
  }, [search])

  useEffect(() => {
    setPage(1)
  }, [tab, startDate, endDate, debouncedSearch])

  useEffect(() => {
    fetchVisits()
  }, [tab, startDate, endDate, debouncedSearch, page])

  // Llegó una solicitud nueva (alerta de Seguridad): recargar sin esperar al usuario
  useEffect(() => {
    if (refreshSignal > 0) fetchVisits()
  }, [refreshSignal])

  // Tras aprobar / rechazar se recarga; si la página quedó vacía se vuelve a la anterior
  const refreshAfterReview = () => {
    onReviewed?.()
    if (visits.length === 1 && page > 1 && tab === 'PENDIENTE') setPage(page - 1)
    else fetchVisits()
  }

  const handleApprove = async (visit: RequestVisitor) => {
    setBusyId(visit.id)
    setError('')
    try {
      await approveVisitor(visit.id)
      onToast?.(`Visita de ${visit.name} aprobada`)
      refreshAfterReview()
    } catch (err) {
      console.error('Error approving visit:', err)
      setError(getErrorMessage(err, 'No se pudo aprobar la solicitud.'))
    } finally {
      setBusyId(null)
    }
  }

  const openReject = (visit: RequestVisitor) => {
    setRejectReason('')
    setRejectError('')
    setToReject(visit)
  }

  const handleReject = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (!toReject) return
    setBusyId(toReject.id)
    setRejectError('')
    try {
      await rejectVisitor(toReject.id, rejectReason.trim() || undefined)
      onToast?.(`Visita de ${toReject.name} rechazada`)
      setToReject(null)
      refreshAfterReview()
    } catch (err) {
      console.error('Error rejecting visit:', err)
      setRejectError(getErrorMessage(err, 'No se pudo rechazar la solicitud.'))
    } finally {
      setBusyId(null)
    }
  }

  return (
    <div className="flex flex-col gap-6">
      {/* Encabezado */}
      <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end">
        <div>
          <p className="text-sm text-[#64748b]">
            {canReview
              ? 'Revisa las solicitudes de visita antes de que lleguen a portería'
              : 'Consulta el estado de las solicitudes. Solo el perfil Seguridad puede aprobarlas o rechazarlas.'}
          </p>
          <h2 className="mt-1 text-[27px] font-bold tracking-[-0.04em] text-[#0f172a]">
            Solicitudes de visita
          </h2>
        </div>
        <button
          onClick={fetchVisits}
          disabled={loading}
          className="flex items-center justify-center gap-2 self-start rounded-lg border border-[#cbd5e1] bg-white px-3.5 py-2.5 text-xs font-bold text-[#334155] shadow-sm transition hover:bg-[#f8fafc] disabled:opacity-50 sm:self-auto"
        >
          <RefreshCw size={15} className={loading ? 'animate-spin text-[#004b93]' : ''} />
          Refrescar
        </button>
      </div>

      <div className="overflow-x-auto rounded-xl border border-[#e2e8f0] bg-white p-5 shadow-[0_1px_2px_rgba(15,23,42,0.03)]">
        {/* Filtros en una fila */}
        <div className="mb-5 flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
          <div className="flex flex-wrap gap-1 rounded-lg bg-[#f1f5f9] p-1" role="tablist">
            {TABS.map((t) => (
              <button
                key={t.id}
                role="tab"
                aria-selected={tab === t.id}
                onClick={() => setTab(t.id)}
                className={`rounded-md px-3 py-1.5 text-xs font-bold transition ${
                  tab === t.id
                    ? 'bg-white text-[#004b93] shadow-sm'
                    : 'text-[#64748b] hover:text-[#0f172a]'
                }`}
              >
                {t.label}
              </button>
            ))}
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <label className="flex items-center gap-2 rounded-lg border border-[#cbd5e1] bg-white px-3 py-2 text-xs font-semibold text-[#475569]">
              <CalendarDays size={15} className="text-[#004b93]" />
              <span className="text-[11px] text-[#64748b]">Desde:</span>
              <input
                type="date"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                className="bg-transparent text-xs font-semibold outline-none"
              />
            </label>
            <label className="flex items-center gap-2 rounded-lg border border-[#cbd5e1] bg-white px-3 py-2 text-xs font-semibold text-[#475569]">
              <CalendarDays size={15} className="text-[#004b93]" />
              <span className="text-[11px] text-[#64748b]">Hasta:</span>
              <input
                type="date"
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
                className="bg-transparent text-xs font-semibold outline-none"
              />
            </label>
            <div className="flex min-w-[200px] items-center gap-2 rounded-lg border border-[#cbd5e1] bg-white px-3 py-2 focus-within:border-[#004b93]">
              <Search size={15} className="text-[#94a3b8]" />
              <input
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Buscar nombre o RUT..."
                className="w-full bg-transparent text-xs outline-none placeholder:text-[#94a3b8]"
              />
            </div>
          </div>
        </div>

        {error && (
          <div className="mb-4 rounded-lg bg-[#fef2f2] p-3 text-xs font-semibold text-[#b91c1c]">
            {error}
          </div>
        )}

        <div className="overflow-x-auto">
          <table className="w-full min-w-[820px] text-left">
            <thead>
              <tr className="border-b border-[#e2e8f0] text-[10px] font-bold uppercase tracking-[0.12em] text-[#94a3b8]">
                <th className="pb-3 pl-1">Visitante</th>
                <th className="pb-3">Fecha y horario</th>
                <th className="pb-3">Zona / Contacto</th>
                <th className="pb-3">Solicitado por</th>
                <th className="pb-3">Estado</th>
                {canReview && <th className="pb-3 pr-1 text-right">Acción</th>}
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr>
                  <td colSpan={canReview ? 6 : 5} className="py-10 text-center text-xs text-[#64748b]">
                    <div className="flex items-center justify-center gap-2">
                      <RefreshCw size={15} className="animate-spin text-[#004b93]" />
                      Cargando solicitudes...
                    </div>
                  </td>
                </tr>
              ) : visits.length === 0 ? (
                <tr>
                  <td colSpan={canReview ? 6 : 5} className="py-10 text-center text-xs text-[#64748b]">
                    {tab === 'PENDIENTE'
                      ? 'No hay solicitudes pendientes.'
                      : 'No hay solicitudes para los filtros seleccionados.'}
                  </td>
                </tr>
              ) : (
                visits.map((visit, rowIndex) => {
                  const isPending = visit.status === 'PENDIENTE' && !visit.isArrivalValidated
                  const busy = busyId === visit.id
                  return (
                    <tr
                      key={visit.id}
                      style={stagger(rowIndex)}
                      className="fa-row border-b border-[#f1f5f9] align-top transition-colors last:border-0 hover:bg-[#f8fafc]"
                    >
                      <td className="py-3.5 pl-1">
                        <p className="text-xs font-bold text-[#0f172a]">
                          {visit.name} {visit.lastnames}
                        </p>
                        <p className="mt-0.5 text-[10px] text-[#94a3b8]">{visit.run}</p>
                      </td>
                      <td className="py-3.5 text-xs text-[#475569]">
                        <p className="font-semibold text-[#0f172a]">
                          {visit.date}
                          {isPeriodVisit(visit) && <span className="text-[#15803d]"> → {visit.endDate}</span>}
                        </p>
                        <p className="text-[10px] text-[#64748b]">
                          {isPeriodVisit(visit)
                            ? 'Visita por período'
                            : `${visit.startHour?.slice(0, 5)} – ${visit.endHour?.slice(0, 5)}`}
                        </p>
                      </td>
                      <td className="py-3.5 text-xs text-[#475569]">
                        <p className="font-semibold text-[#0f172a]">{visit.zone?.name || '—'}</p>
                        <p className="text-[10px] text-[#64748b]">
                          {visit.contactUser?.username || 'Sin contacto'}
                        </p>
                      </td>
                      <td className="py-3.5 text-xs text-[#475569]">
                        <p>{visit.creator?.username || '—'}</p>
                        <p className="text-[10px] text-[#94a3b8]">{formatDateTime(visit.createdAt)}</p>
                      </td>
                      <td className="py-3.5">
                        <VisitStatusBadge status={visit.status} />
                        {visit.status !== 'PENDIENTE' && (
                          <p className="mt-1 text-[10px] text-[#94a3b8]">
                            {visit.reviewer?.username ? `por ${visit.reviewer.username} · ` : ''}
                            {formatDateTime(visit.reviewedAt)}
                          </p>
                        )}
                        {visit.rejectionReason && (
                          <p className="mt-1 max-w-[220px] text-[10px] text-[#b91c1c]">
                            Motivo: {visit.rejectionReason}
                          </p>
                        )}
                      </td>
                      {canReview && (
                      <td className="py-3.5 pr-1">
                        {isPending ? (
                          <div className="flex justify-end gap-1.5">
                            <button
                              onClick={() => handleApprove(visit)}
                              disabled={busy}
                              className="flex items-center gap-1 rounded-lg bg-[#16a34a] px-3 py-1.5 text-[11px] font-bold text-white transition hover:bg-[#15803d] disabled:opacity-60"
                            >
                              <Check size={13} /> Aprobar
                            </button>
                            <button
                              onClick={() => openReject(visit)}
                              disabled={busy}
                              className="flex items-center gap-1 rounded-lg border border-[#fecaca] bg-white px-3 py-1.5 text-[11px] font-bold text-[#b91c1c] transition hover:bg-[#fef2f2] disabled:opacity-60"
                            >
                              <X size={13} /> Rechazar
                            </button>
                          </div>
                        ) : (
                          <span className="block text-right text-[10px] text-[#94a3b8]">—</span>
                        )}
                      </td>
                      )}
                    </tr>
                  )
                })
              )}
            </tbody>
          </table>
        </div>

        {!loading && (
          <div className="mt-4 flex flex-wrap items-center justify-between gap-2 border-t border-[#edf1ee] pt-4">
            <span className="text-xs text-[#7e8984]">
              {total} {total === 1 ? 'solicitud' : 'solicitudes'}
            </span>
            <div className="flex items-center gap-2">
              <button
                type="button"
                disabled={page <= 1}
                onClick={() => setPage(page - 1)}
                className="rounded-md border border-[#dce5e0] px-2.5 py-1.5 text-xs font-semibold text-[#50615a] transition hover:bg-[#f6f8f7] disabled:cursor-not-allowed disabled:opacity-40"
              >
                Anterior
              </button>
              <span className="text-xs text-[#7e8984]">
                Página {page} de {totalPages}
              </span>
              <button
                type="button"
                disabled={page >= totalPages}
                onClick={() => setPage(page + 1)}
                className="rounded-md border border-[#dce5e0] px-2.5 py-1.5 text-xs font-semibold text-[#50615a] transition hover:bg-[#f6f8f7] disabled:cursor-not-allowed disabled:opacity-40"
              >
                Siguiente
              </button>
            </div>
          </div>
        )}
      </div>

      {toReject && (
        <Modal title="Rechazar solicitud" onClose={() => setToReject(null)}>
          <form onSubmit={handleReject} autoComplete="off" className="space-y-4">
            <p className="text-sm text-[#475569]">
              Vas a rechazar la visita de{' '}
              <strong>
                {toReject.name} {toReject.lastnames}
              </strong>{' '}
              del {toReject.date}. No podrá ingresar en portería.
            </p>
            <label className="block">
              <span className="mb-1.5 block text-xs font-bold text-[#334155]">
                Motivo <span className="font-normal text-[#94a3b8]">(opcional)</span>
              </span>
              <textarea
                value={rejectReason}
                onChange={(e) => setRejectReason(e.target.value)}
                rows={3}
                autoFocus
                placeholder="Ej. No se encuentra autorizado por la gerencia"
                className="w-full resize-none rounded-lg border border-[#cbd5e1] bg-white px-3 py-2.5 text-sm outline-none transition placeholder:text-[#94a3b8] focus:border-[#004b93] focus:ring-2 focus:ring-[#004b93]/10"
              />
            </label>
            {rejectError && (
              <div className="rounded-lg bg-[#fef2f2] p-3 text-xs font-semibold text-[#b91c1c]">
                {rejectError}
              </div>
            )}
            <div className="flex justify-end gap-2">
              <button
                type="button"
                onClick={() => setToReject(null)}
                className="rounded-lg border border-[#cbd5e1] px-4 py-2.5 text-xs font-bold text-[#334155] hover:bg-[#f8fafc]"
              >
                Cancelar
              </button>
              <button
                type="submit"
                disabled={busyId === toReject.id}
                className="rounded-lg bg-[#b91c1c] px-4 py-2.5 text-xs font-bold text-white hover:bg-[#991b1b] disabled:opacity-60"
              >
                {busyId === toReject.id ? 'Rechazando...' : 'Rechazar solicitud'}
              </button>
            </div>
          </form>
        </Modal>
      )}
    </div>
  )
}
